2041	// reviewRunRuntimeDir creates the private directory of one run. Every run of
2042	// an attempt uses the same path, so a resumed reviewer session, which still
2043	// refers to the sealed checkout it worked in, finds the checkout recreated
2044	// there after the interrupted run removed it (spec
2045	// pose-review-resume-keeps-the-sealed-checkout R1). The directory is created
2046	// exclusively and never followed: when the path already exists, from an
2047	// unfinished cleanup or from someone else, the run fails instead of sharing
2048	// it. A run without an attempt keeps a random name.
2049	func reviewRunRuntimeDir(attemptID string) (string, error) {
2050		dir, ok := reviewRunRuntimeDirPath(attemptID)
2051		if !ok {
2052			return os.MkdirTemp("", "pose-review-run-*")
2053		}
2054		if err := os.Mkdir(dir, 0o700); err != nil {
2055			if errors.Is(err, fs.ErrExist) {
2056				return "", fmt.Errorf("the attempt's runtime directory %s already exists; an earlier run of the attempt did not clean up, or another process holds the path; remove it, then run again", dir)
2057			}
2058			return "", err
2059		}
2060		return dir, nil
2061	}
2062	
2063	// reviewRunRuntimeDirPath is the runtime directory every run of an attempt
2064	// uses, or false for a run without an attempt.
2065	func reviewRunRuntimeDirPath(attemptID string) (string, bool) {
2066		if !reviewAttemptIDRE.MatchString(attemptID) {
2067			return "", false
2068		}
2069		return filepath.Join(os.TempDir(), "pose-review-run-"+attemptID[len("rat-"):len("rat-")+32]), true
2070	}
