674	// removeReviewGoBuildLeftovers removes the Go build directories a reviewer's
675	// interrupted `go test` or `go build` left at the top of the run's runtime
676	// directory, each under its own bounded inventory, before the runtime's own
677	// inventory, which a single test binary can exceed (spec
678	// pose-review-cleanup-removes-go-build-leftovers). Only a real directory is
679	// removed; the platform implementation opens it without blocking and only as
680	// a directory, so a link, a FIFO or any other entry stays for the runtime
681	// inventory to judge.
682	func removeReviewGoBuildLeftovers(root *os.Root) error {
683		// The top level is read in bounded batches and each go-build directory
684		// is removed as it is read, so nothing accumulates; only the other
685		// entries, which the runtime inventory will judge, count against its
686		// bound (review rounds 5 and 6, N6 and N10).
687		dir, err := root.Open(".")
688		if err != nil {
689			return fmt.Errorf("runtime cleanup inventory incomplete; resources retained")
690		}
691		defer dir.Close()
692		others := 0
693		for {
694			batch, err := dir.Readdirnames(256)
695			for _, name := range batch {
696				if !reviewGoBuildDir.MatchString(name) {
697					others++
698					if others > reviewRuntimeMaxEntries {
699						return fmt.Errorf("runtime cleanup inventory incomplete; resources retained")
700					}
701					continue
702				}
703				if err := removeReviewGoBuildDir(root, name); err != nil {
704					return err
705				}
706			}
707			if len(batch) == 0 {
708				if err == nil || errors.Is(err, io.EOF) {
709					return nil
710				}
711				return fmt.Errorf("runtime cleanup inventory incomplete; resources retained")
712			}
713		}
714	}
